    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        List<Record> records = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            long id = Long.parseLong(st.nextToken());
            String p = st.nextToken();
            String name = st.nextToken();
            records.add(new Record(id, p.equals("null") ? -1 : Long.parseLong(p), name));
        }
        List<Node> roots = convertToTree(records);
        StringBuilder sb = new StringBuilder();
        Deque<Object[]> stack = new ArrayDeque<>();
        for (int i = roots.size() - 1; i >= 0; i--) stack.push(new Object[]{roots.get(i), 0});
        while (!stack.isEmpty()) {
            Object[] top = stack.pop();
            Node node = (Node) top[0];
            int depth = (Integer) top[1];
            sb.append(depth).append(' ').append(node.id).append(' ').append(node.name).append('\n');
            for (int i = node.children.size() - 1; i >= 0; i--) stack.push(new Object[]{node.children.get(i), depth + 1});
        }
        System.out.print(sb);
    }
}

