def gen(rng):
    NAMES = 'abcdefghijklmnopqrstuvwxyz0123456789._'
    def mk(n, parent_pick, id_hi=10**6):
        ids = rng.sample(range(1, id_hi + 1), n)
        par = []
        for i in range(n):
            par.append(parent_pick(i))
        recs = []
        for i in range(n):
            name = ''.join(rng.choice(NAMES) for _ in range(rng.randint(1, 8)))
            recs.append((ids[i], 'null' if par[i] is None else ids[par[i]], name))
        rng.shuffle(recs)
        return str(n) + '\n' + '\n'.join(f'{a} {b} {c}' for a, b, c in recs)
    def rand_tree(n, root_p):
        def pick(i):
            if i == 0 or rng.random() < root_p:
                return None
            return rng.randrange(i)
        return mk(n, pick, 10**6 if n > 1000 else 200)
    tests = ['4\n4 2 Resume.pdf\n1 null Root\n2 1 Documents\n3 null Config', '1\n5 null x',
             '3\n1 null a\n2 null a\n3 null a', '3\n3 2 c\n2 1 b\n1 null a', '3\n1 null r\n3 1 z\n2 1 y']
    for n in (2, 3, 4, 6, 8, 10, 14):
        for _ in range(3):
            tests.append(rand_tree(n, rng.choice([0.05, 0.2, 0.5])))
    N = 50000
    tests.append(rand_tree(N, 0.001))
    tests.append(rand_tree(N, 0.3))
    tests.append(mk(N, lambda i: None))
    tests.append(mk(N, lambda i: None if i == 0 else 0))
    depth = [0] * N
    def deep_pick(i):
        if i == 0:
            return None
        if i < 5000:
            depth[i] = i
            return i - 1
        while True:
            p = rng.randrange(i)
            if depth[p] < 4999:
                depth[i] = depth[p] + 1
                return p
    tests.append(mk(N, deep_pick))
    return tests
